Great question! Based on my exploration of the codebase, here's a comprehensive guide on how to test the Writing Tools API integration in this project.

---

## How to Test Writing Tools API Integration

The writing tools system has **4 layers** you can test, from unit to integration:

---

## 1. 🧪 Unit Test: Flow Functions

**Location:** `src/modules/ai/infrastructure/flows/__tests__/`

These test individual AI flow logic by mocking Genkit. Follow the pattern from `summarize-text.test.ts`:

```typescript
// src/modules/ai/infrastructure/flows/__tests__/paraphrase-text.test.ts

import { describe, it, expect, jest, beforeEach } from '@jest/globals';

// Mock Genkit BEFORE importing the flow
jest.mock('@/modules/ai/infrastructure/services/Genkit', () => ({
  ai: {
    defineFlow: jest.fn((_config, fn) => fn), // returns the inner fn directly
    definePrompt: jest.fn(() => jest.fn()),
  },
}));

// Mock the prompt result
const mockPromptFn = jest.fn().mockResolvedValue({
  output: { paraphrasedText: 'Rewritten sentence.' },
});

jest.mock('@/modules/ai/infrastructure/prompts/General', () => ({
  getParaphrasePrompt: jest.fn(() => mockPromptFn),
}));

import { paraphraseTextWrapper } from '../writing/paraphrase-text';
import { ParaphraseInputSchema } from '@/modules/ai/domain/schemas';

describe('paraphraseText flow', () => {
  it('validates input schema correctly', () => {
    const result = ParaphraseInputSchema.safeParse({
      text: 'Hello world',
      tone: 'formal',
      language: 'en',
    });
    expect(result.success).toBe(true);
  });

  it('rejects empty text', () => {
    const result = ParaphraseInputSchema.safeParse({ text: '' });
    expect(result.success).toBe(false);
  });

  it('returns paraphrased content', async () => {
    const output = await paraphraseTextWrapper({
      text: 'Hello world',
      tone: 'formal',
      language: 'en',
    });
    expect(output).toEqual({ paraphrasedText: 'Rewritten sentence.' });
  });
});
```

---

## 2. 🧪 Unit Test: RunAiToolUseCase

Test the orchestration logic (credits, rate limiting, logging) with mocked repositories:

```typescript
// src/modules/ai/application/use-cases/__tests__/RunAiToolUseCase.test.ts

import 'reflect-metadata';
import { RunAiToolUseCase } from '../RunAiToolUseCase';
import { Result } from '@/infrastructure/utils/result';

// Mock all dependencies
const mockRegistry = {
  getTool: jest.fn(),
};
const mockAiService = {
  runFlow: jest.fn(),
};
const mockCreditRepo = {
  getBalance: jest.fn(),
  deduct: jest.fn(),
  refund: jest.fn(),
};
const mockLogRepo = {
  create: jest.fn(),
};
const mockRateLimiter = {
  check: jest.fn(),
};

describe('RunAiToolUseCase', () => {
  let useCase: RunAiToolUseCase;

  beforeEach(() => {
    jest.clearAllMocks();
    useCase = new RunAiToolUseCase(
      mockRegistry as any,
      mockAiService as any,
      mockCreditRepo as any,
      mockLogRepo as any,
      mockRateLimiter as any
    );
  });

  it('returns error when tool is not registered', async () => {
    mockRegistry.getTool.mockReturnValue(null);

    const result = await useCase.execute({
      toolName: 'nonexistent-tool',
      input: {},
      user: null,
      clientIp: '127.0.0.1',
    });

    expect(result.isFailure).toBe(true);
  });

  it('deducts credits and calls the flow', async () => {
    mockRegistry.getTool.mockReturnValue({
      flow: jest.fn().mockResolvedValue({ text: 'output' }),
      schema: { parse: jest.fn((x) => x) },
      creditCost: 1,
      isFreeForGuests: false,
    });
    mockCreditRepo.getBalance.mockResolvedValue(10);
    mockCreditRepo.deduct.mockResolvedValue(undefined);
    mockLogRepo.create.mockResolvedValue(undefined);
    mockAiService.runFlow.mockResolvedValue(
      Result.ok({ text: 'output' })
    );

    const result = await useCase.execute({
      toolName: 'summarize',
      input: { text: 'Some text' },
      user: { id: 'user-1', role: 'user' } as any,
      clientIp: '127.0.0.1',
    });

    expect(mockCreditRepo.deduct).toHaveBeenCalled();
    expect(result.isSuccess).toBe(true);
  });

  it('refunds credits when flow fails', async () => {
    mockRegistry.getTool.mockReturnValue({
      flow: jest.fn(),
      schema: { parse: jest.fn((x) => x) },
      creditCost: 2,
      isFreeForGuests: false,
    });
    mockCreditRepo.getBalance.mockResolvedValue(10);
    mockCreditRepo.deduct.mockResolvedValue(undefined);
    mockAiService.runFlow.mockResolvedValue(
      Result.fail({ message: 'Model timeout' })
    );

    const result = await useCase.execute({
      toolName: 'summarize',
      input: { text: 'Some text' },
      user: { id: 'user-1', role: 'user' } as any,
      clientIp: '127.0.0.1',
    });

    expect(mockCreditRepo.refund).toHaveBeenCalled();
    expect(result.isFailure).toBe(true);
  });
});
```

---

## 3. 🧪 Unit Test: useWritingTool Hook

Test the React hook using React Testing Library:

```typescript
// src/modules/ai/adapters/hooks/writing-tools/__tests__/use-writing-tool.test.tsx

import 'reflect-metadata';
import { renderHook, act } from '@testing-library/react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { useWritingTool } from '../use-writing-tool';
import { Result } from '@/infrastructure/utils/result';
import React from 'react';

// Mock the API client resolved from DI
jest.mock('@/infrastructure/di/container', () => ({
  container: {
    resolve: jest.fn(() => ({
      executeToolApi: jest.fn().mockResolvedValue(
        Result.ok({ summarizedText: 'Summary result' })
      ),
    })),
  },
}));

// Mock AuthContext
jest.mock('@/context/AuthContext', () => ({
  useAuth: () => ({
    user: { uid: 'test-user' },
    updateUsage: jest.fn(),
  }),
}));

const wrapper = ({ children }: { children: React.ReactNode }) => (
  <QueryClientProvider client={new QueryClient()}>
    {children}
  </QueryClientProvider>
);

describe('useWritingTool', () => {
  it('calls the API and returns result', async () => {
    const { result } = renderHook(
      () => useWritingTool('summarize'),
      { wrapper }
    );

    await act(async () => {
      await result.current.execute({ text: 'Long article text...' });
    });

    expect(result.current.data).toEqual({ summarizedText: 'Summary result' });
    expect(result.current.isError).toBe(false);
  });

  it('surfaces errors from the API', async () => {
    jest.mock('@/infrastructure/di/container', () => ({
      container: {
        resolve: jest.fn(() => ({
          executeToolApi: jest.fn().mockResolvedValue(
            Result.fail({ message: 'Insufficient credits' })
          ),
        })),
      },
    }));

    const { result } = renderHook(
      () => useWritingTool('summarize'),
      { wrapper }
    );

    await act(async () => {
      await result.current.execute({ text: 'text' });
    });

    expect(result.current.isError).toBe(true);
  });
});
```

---

## 4. 🌐 Integration Test: API Route (HTTP-level)

Test the full request/response cycle for `POST /api/writing-tools/[tool]`:

```typescript
// src/app/api/writing-tools/__tests__/route.integration.test.ts

import { POST } from '../[tool]/route';
import { NextRequest } from 'next/server';

// Mock the DI container and controller
jest.mock('@/infrastructure/di/container', () => ({
  container: {
    resolve: jest.fn(() => ({
      runTool: jest.fn().mockResolvedValue(
        // Return a Result.ok with mocked data
        { isSuccess: true, getValue: () => ({ summarizedText: 'Test summary' }) }
      ),
    })),
  },
}));

function makeRequest(toolName: string, body: object): NextRequest {
  return new NextRequest(
    `http://localhost:3000/api/writing-tools/${toolName}`,
    {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    }
  );
}

describe('POST /api/writing-tools/[tool]', () => {
  it('returns 200 with AI output for valid input', async () => {
    const req = makeRequest('summarize', {
      text: 'A long piece of text to summarize.',
      language: 'en',
    });

    const response = await POST(req, { params: { tool: 'summarize' } });
    const data = await response.json();

    expect(response.status).toBe(200);
    expect(data).toHaveProperty('summarizedText');
  });

  it('returns 400 for invalid input schema', async () => {
    const req = makeRequest('summarize', { text: '' }); // empty text fails validation

    const response = await POST(req, { params: { tool: 'summarize' } });

    expect(response.status).toBe(400);
  });

  it('returns 404 for unknown tool', async () => {
    const req = makeRequest('unknown-tool', { text: 'Hello' });

    const response = await POST(req, { params: { tool: 'unknown-tool' } });

    expect(response.status).toBe(404);
  });
});
```

---

## 5. 🚀 Running the Tests

```bash
# Run all AI-related tests
npm test -- --testPathPattern="modules/ai"

# Run only flow tests
npm test -- --testPathPattern="flows/__tests__"

# Run a specific test file
npm test -- --testPathPattern="summarize-text"

# Run with coverage
npm test -- --coverage --testPathPattern="modules/ai"

# Type-check before testing (always do this first!)
npm run typecheck && npm test
```

---

## 6. 📋 Quick Reference: What to Mock Per Test Level

| Layer | What to Mock |
|-------|-------------|
| **Flow tests** | `Genkit.ts` (`ai.defineFlow`, `ai.definePrompt`) |
| **UseCase tests** | All injected repositories + `IAiService` |
| **Hook tests** | `container.resolve()` → API client, `useAuth()` |
| **Route tests** | `container.resolve()` → `AiController` |

---

## 7. 💡 Tips Specific to This Codebase

- **Always import `reflect-metadata`** at the top of test files that use tsyringe DI classes
- **Use `Result.ok(...)` / `Result.fail(...)`** when mocking service returns — never raw values
- **Call `.getValue()`** (not `.value`) when unwrapping a success Result
- **Guest tool access**: To test guest flows, set `user: null` and ensure the tool has `isFreeForGuests: true` in registry
- **Credit refund test**: Set `mockAiService.runFlow` to return `Result.fail(...)` and assert `mockCreditRepo.refund` was called

