  40     const mode = (input.mode || 'standard') as ParaphraseMode;
  41     const instruction = styleDescriptions[mode] || styleDescriptions.standard;
  42     const result = await paraphrasePrompt({ text: input.text, mode: input.mode, instruction } as any);
