   1 import { inject, injectable } from "tsyringe";
   2 import type { IAiService } from "../../domain/services/IAiService";
   3 import { IAiServiceToken } from "../../domain/services/IAiService";
   4 import type { IGenerationLogRepository } from "../../domain/repositories/IGenerationLogRepository";
   5 import { IGenerationLogRepositoryToken } from "../../domain/repositories/IGenerationLogRepository";
   6 import { DeductCreditsUseCase } from "@/modules/users/application/use-cases/DeductCreditsUseCase";
   7 import { WritingToolRegistry } from "../services/WritingToolRegistry";
   8 import { Result } from "@/infrastructure/utils/result";
   9 import { AiError } from "../../domain/errors/AiErrors";
  10 import { rateLimiter } from "@/infrastructure/security/rate-limiter";
  11 
  12 export interface RunAiToolInput<TInput> {
  13     userId: string;
  14     toolName: string;
  15     input: TInput;
  16     ip?: string;
  17 }
  18 
  19 @injectable()
  20 export class RunAiToolUseCase {
  21     constructor(
  22         @inject(IAiServiceToken)
  23         private aiService: IAiService,
  24         @inject(IGenerationLogRepositoryToken)
  25         private generationLogRepository: IGenerationLogRepository,
  26         @inject(DeductCreditsUseCase) private deductCreditsUseCase: DeductCreditsUseCase,
  27         @inject(WritingToolRegistry)
  28         private writingToolRegistry: WritingToolRegistry
  29     ) {}
  30 
  31     async execute<TInput, TOutput>(params: RunAiToolInput<TInput>): Promise<Result<TOutput, AiError>> {
  32         const { userId, toolName, input, ip } = params;
  33 
  34         const config = this.writingToolRegistry.getTool(toolName);
  35         if (!config) {
  36             return Result.fail(AiError.notFound(`Tool ${toolName} not found in registry.`));
  37         }
  38 
  39         const { flow, creditCost, isFreeForGuests } = config;
  40 
  41         // 1. Handle guest access
  42         const isGuest = userId === 'guest';
  43         if (isGuest) {
  44             if (!isFreeForGuests) {
  45                 return Result.fail(AiError.unauthorized(`The ${toolName} tool requires a registered account.`));
  46             }
  47 
  48             // Apply daily limit for guests (5 requests per 24h)
  49             const limiterResult = await rateLimiter.check('guest-writing-tools', ip || 'unknown', 5, 24 * 60 * 60 * 1000);
  50             if (!limiterResult.allowed) {
  51                 return Result.fail(AiError.unauthorized("Guest daily limit exceeded (5 requests/day). Please sign up for unlimited access."));
  52             }
  53         }
  54 
  55         // 2. Pre-deduct credits or check free tier for registered users
  56         let creditsDeducted = false;
  57         let isFreeTierRegistered = false;
  58 
  59         if (!isGuest && creditCost > 0) {
  60             const deductResult = await this.deductCreditsUseCase.execute(userId, creditCost);
  61             
  62             if (deductResult.isFailure) {
  63                 // Check if they can use the free registered tier (10 generations/day)
  64                 if (isFreeForGuests) {
  65                     const limiterResult = await rateLimiter.check('registered-free-tier', userId, 10, 24 * 60 * 60 * 1000);
  66                     if (!limiterResult.allowed) {
  67                         return Result.fail(AiError.unauthorized("Daily free tier limit exceeded (10 generations/day). Please top up your credits."));
  68                     }
  69                     isFreeTierRegistered = true;
  70                 } else {
  71                     return Result.fail(AiError.internal(`Insufficient credits and tool is not free tier compatible.`));
  72                 }
  73             } else {
  74                 creditsDeducted = true;
  75             }
  76         }
  77 
  78         // 3. Run the AI Flow
  79         try {
  80             const aiResult = await this.aiService.runFlow<TInput, TOutput>(flow, input, toolName);
  81             
  82             if (aiResult.isFailure) {
  83                 // Refund credits if AI flow fails
  84                 if (creditsDeducted) {
  85                     await this.deductCreditsUseCase.execute(userId, -creditCost);
  86                 }
  87                 return aiResult;
  88             }
  89 
  90             const result = aiResult.getValue();
  91 
  92             // 4. Log the generation
  93             await this.generationLogRepository.log({
  94                 agentId: toolName,
  95                 userId: userId,
  96                 input: input,
  97                 output: result,
  98                 creditCost: (isGuest || isFreeTierRegistered) ? 0 : creditCost
  99             });
