 101             // 5. Wrap response with usage metadata (only if result is an object)
 102             if (typeof result === 'string') {
 103                 return Result.ok(result as any);
 104             }
 105 
 106             const usage = isGuest 
 107                 ? await rateLimiter.getStats('guest-writing-tools', ip || 'unknown', 5, 24 * 60 * 60 * 1000)
 108                 : isFreeTierRegistered 
 109                     ? await rateLimiter.getStats('registered-free-tier', userId, 10, 24 * 60 * 60 * 1000)
 110                     : null;
 111 
 112             return Result.ok({
 113                 ...(result as any),
 114                 usageMetadata: usage
 115             } as any);
 116         } catch (error: any) {
 117             // Refund credits on unexpected error
 118             if (creditsDeducted) {
