  29           tier: 'guest', // will be refined by AuthContext refresh
  30           resetAt: data.usageMetadata.resetAt
  31         } as any);
  32       }
  33       if (options?.onSuccess) {
  34         // @ts-expect-error - Type mismatch with TanStack Query callback signature
  35         options.onSuccess(data, variables, context);
