{"file_path": "src/modules/ai/infrastructure/flows/__tests__/paraphrase-text.test.ts", "initial_content": "import { paraphraseText } from '../writing/paraphrase-text';
import { ai } from '@/modules/ai/infrastructure/services/Genkit';
import { type ParaphraseInput } from '@/modules/ai/domain/schemas';

// Mock the genkit `ai` object. defineFlow returns the implementation directly.
jest.mock('@/modules/ai/infrastructure/services/Genkit', () => ({
  ai: {
    definePrompt: jest.fn(),
    defineFlow: jest.fn((config, implementation) => implementation),
  },
  MODEL_BY_TASK: {},
}));

const mockDefinePrompt = ai.definePrompt as jest.Mock;

describe('paraphraseText Flow', () => {
  let mockPromptFn: jest.Mock;

  beforeEach(() => {
    jest.clearAllMocks();
    mockPromptFn = jest.fn();
    mockDefinePrompt.mockReturnValue(mockPromptFn);
  });

  it('should call the paraphrase prompt in "standard" mode', async () => {
    const mockInput: ParaphraseInput = {
      text: 'The quick brown fox jumps over the lazy dog.',
      mode: 'standard',
    };
    mockPromptFn.mockResolvedValue({ text: 'A swift auburn fox leaps over the idle dog.' });

    const result = await paraphraseText(mockInput);

    expect(mockDefinePrompt).toHaveBeenCalled();
    expect(mockPromptFn).toHaveBeenCalledWith(
      expect.objectContaining({
        text: mockInput.text,
        mode: mockInput.mode,
        instruction: expect.stringContaining('clarity'),
      }),
    );
    expect(result).toBe('A swift auburn fox leaps over the idle dog.');
  });

  it('should use "formal" mode instruction when mode is formal', async () => {
    const mockInput: ParaphraseInput = {
      text: 'Hey, can you help me out here?',
      mode: 'formal',
    };
    mockPromptFn.mockResolvedValue({ text: 'Could you please provide your assistance in this matter?' });

    await paraphraseText(mockInput);

    expect(mockPromptFn).toHaveBeenCalledWith(
      expect.objectContaining({
        instruction: expect.stringContaining('formal'),
      }),
    );
  });

  it('should use "fluent" mode instruction when mode is fluent', async () => {
    const mockInput: ParaphraseInput = {
      text: 'I am going to the store.',
      mode: 'fluent',
    };
    mockPromptFn.mockResolvedValue({ text: "I'm heading to the store." });

    await paraphraseText(mockInput);

    expect(mockPromptFn).toHaveBeenCalledWith(
      expect.objectContaining({
        instruction: expect.stringContaining('fluent'),
      }),
    );
  });

  it('should use "creative" mode instruction when mode is creative', async () => {
    const mockInput: ParaphraseInput = {
      text: 'The sun is bright today.',
      mode: 'creative',
    };
    mockPromptFn.mockResolvedValue({ text: 'Golden rays blazed gloriously across the afternoon sky.' });

    await paraphraseText(mockInput);

    expect(mockPromptFn).toHaveBeenCalledWith(
      expect.objectContaining({
        instruction: expect.stringContaining('creative'),
      }),
    );
  });

  it('should use "simplify" mode instruction when mode is simplify', async () => {
    const mockInput: ParaphraseInput = {
      text: 'The utilization of renewable energy sources mitigates environmental degradation.',
      mode: 'simplify',
    };
    mockPromptFn.mockResolvedValue({ text: 'Using clean energy helps the environment.' });

    await paraphraseText(mockInput);

    expect(mockPromptFn).toHaveBeenCalledWith(
      expect.objectContaining({
        instruction: expect.stringContaining('simpler'),
      }),
    );
  });

  it('should throw an error for empty input text', async () => {
    const mockInput = { text: '', mode: 'standard' };
    await expect(paraphraseText(mockInput as ParaphraseInput)).rejects.toThrow();
  });

  it('should throw an error for invalid mode enum', async () => {
    const mockInput = { text: 'Some valid text', mode: 'invalid-mode' };
    await expect(paraphraseText(mockInput as any)).rejects.toThrow();
  });

  it('should throw an error if the model returns empty output', async () => {
    const mockInput: ParaphraseInput = { text: 'Some valid text.', mode: 'standard' };
    mockPromptFn.mockResolvedValue({ text: '' });

    await expect(paraphraseText(mockInput)).rejects.toThrow('Failed to paraphrase text.');
  });

  it('should strip triple-dash separators from the output', async () => {
    const mockInput: ParaphraseInput = { text: 'Some text.', mode: 'standard' };
    mockPromptFn.mockResolvedValue({ text: '---Paraphrased text here---' });

    const result = await paraphraseText(mockInput);
    expect(result).not.toContain('---');
    expect(result).toBe('Paraphrased text here');
  });
});
"}

{"file_path": "src/modules/ai/infrastructure/flows/__tests__/grammar-checker.test.ts", "initial_content": "import { grammarCheck } from '../writing/grammar-checker';
import { ai } from '@/modules/ai/infrastructure/services/Genkit';
import { type GrammarCheckInput } from '@/modules/ai/domain/schemas';

// Mock the genkit `ai` object. defineFlow returns the implementation directly.
jest.mock('@/modules/ai/infrastructure/services/Genkit', () => ({
  ai: {
    definePrompt: jest.fn(),
    defineFlow: jest.fn((config, implementation) => implementation),
  },
  MODEL_BY_TASK: {},
}));

const mockDefinePrompt = ai.definePrompt as jest.Mock;

describe('grammarCheck Flow', () => {
  let mockPromptFn: jest.Mock;

  beforeEach(() => {
    jest.clearAllMocks();
    mockPromptFn = jest.fn();
    mockDefinePrompt.mockReturnValue(mockPromptFn);
  });

  it('should return corrected text from the model', async () => {
    const mockInput: GrammarCheckInput = {
      text: 'She dont know nothing about it.',
    };
    const corrected = "She doesn't know anything about it.";
    mockPromptFn.mockResolvedValue({ text: corrected });

    const result = await grammarCheck(mockInput);

    expect(mockDefinePrompt).toHaveBeenCalled();
    expect(mockPromptFn).toHaveBeenCalledWith(expect.objectContaining({ text: mockInput.text }));
    expect(result).toBe(corrected);
  });

  it('should return the text unchanged if no grammar errors exist', async () => {
    const mockInput: GrammarCheckInput = {
      text: 'The quick brown fox jumps over the lazy dog.',
    };
    mockPromptFn.mockResolvedValue({ text: mockInput.text });

    const result = await grammarCheck(mockInput);

    expect(result).toBe(mockInput.text);
  });

  it('should preserve markdown formatting in the output', async () => {
    const mockInput: GrammarCheckInput = {
      text: '## Heading\n\nThis are a test.',
    };
    const corrected = '## Heading\n\nThis is a test.';
    mockPromptFn.mockResolvedValue({ text: corrected });

    const result = await grammarCheck(mockInput);

    expect(result).toContain('## Heading');
    expect(result).toBe(corrected);
  });

  it('should fall back to result.output if result.text is empty', async () => {
    const mockInput: GrammarCheckInput = { text: 'He go to school every day.' };
    mockPromptFn.mockResolvedValue({ text: '', output: 'He goes to school every day.' });

    const result = await grammarCheck(mockInput);
    expect(result).toBe('He goes to school every day.');
  });

  it('should throw an error if the model returns empty text', async () => {
    const mockInput: GrammarCheckInput = { text: 'Some text with errors.' };
    mockPromptFn.mockResolvedValue({ text: '', output: '' });

    await expect(grammarCheck(mockInput)).rejects.toThrow('Grammar check failed.');
  });

  it('should throw an error for empty input text', async () => {
    const mockInput = { text: '' };
    await expect(grammarCheck(mockInput as GrammarCheckInput)).rejects.toThrow();
  });

  it('should trim whitespace from the output', async () => {
    const mockInput: GrammarCheckInput = { text: 'She go to the market.' };
    mockPromptFn.mockResolvedValue({ text: '  She goes to the market.  ' });

    const result = await grammarCheck(mockInput);
    expect(result).toBe('She goes to the market.');
  });

  it('should call definePrompt with the correct model', async () => {
    const mockInput: GrammarCheckInput = { text: 'He are my friend.' };
    mockPromptFn.mockResolvedValue({ text: 'He is my friend.' });

    await grammarCheck(mockInput);

    expect(mockDefinePrompt).toHaveBeenCalledWith(
      expect.objectContaining({
        name: 'grammarCheckPrompt',
        model: 'ollama/gemma:2b',
      }),
    );
  });
});
"}

