{"file_path": "src/modules/ai/adapters/api-client/__tests__/WritingToolsApiClient.test.ts", "initial_content": "import 'reflect-metadata';
import { WritingToolsApiClient } from '../WritingToolsApiClient';
import { ApiError } from '@/infrastructure/api/ApiService';

// ---------------------------------------------------------------------------
// Mock apiService
// ---------------------------------------------------------------------------
jest.mock('@/infrastructure/api/ApiService', () => {
  const actual = jest.requireActual('@/infrastructure/api/ApiService');
  return {
    ...actual,
    apiService: jest.fn(),
  };
});

import { apiService } from '@/infrastructure/api/ApiService';

const mockApiService = apiService as jest.Mock;

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

describe('WritingToolsApiClient', () => {
  let client: WritingToolsApiClient;

  beforeEach(() => {
    jest.clearAllMocks();
    client = new WritingToolsApiClient();
  });

  // ── executeToolApi ─────────────────────────────────────────────────────────

  describe('executeToolApi', () => {
    it('calls apiService with correct endpoint and method', async () => {
      const responseData = { summarizedText: 'A short summary.' };
      mockApiService.mockResolvedValue(responseData);

      await client.executeToolApi('summarize', { text: 'Long text', length: 'short' });

      expect(mockApiService).toHaveBeenCalledWith({
        endpoint: '/api/writing-tools/summarize',
        method: 'POST',
        data: { text: 'Long text', length: 'short' },
      });
    });

    it('returns Result.ok with the response data on success', async () => {
      const responseData = { summarizedText: 'Summary here.' };
      mockApiService.mockResolvedValue(responseData);

      const result = await client.executeToolApi('summarize', { text: 'Hello' });

      expect(result.isSuccess).toBe(true);
      expect(result.getValue()).toEqual(responseData);
    });

    it('returns Result.fail with ApiError when apiService throws an ApiError', async () => {
      const apiErr = new ApiError('Insufficient credits', 402);
      mockApiService.mockRejectedValue(apiErr);

      const result = await client.executeToolApi('summarize', { text: 'Hello' });

      expect(result.isFailure).toBe(true);
      expect(result.error).toBeInstanceOf(ApiError);
      expect(result.error?.message).toBe('Insufficient credits');
      expect(result.error?.statusCode).toBe(402);
    });

    it('wraps a generic Error into ApiError with status 500', async () => {
      mockApiService.mockRejectedValue(new Error('Network failure'));

      const result = await client.executeToolApi('paraphrase', { text: 'Hello', mode: 'formal' });

      expect(result.isFailure).toBe(true);
      expect(result.error).toBeInstanceOf(ApiError);
      expect(result.error?.message).toBe('Network failure');
      expect(result.error?.statusCode).toBe(500);
    });

    it('wraps an unknown thrown value into ApiError', async () => {
      mockApiService.mockRejectedValue('something strange');

      const result = await client.executeToolApi('humanize', { text: 'Hello' });

      expect(result.isFailure).toBe(true);
      expect(result.error).toBeInstanceOf(ApiError);
      expect(result.error?.message).toBe('Unknown error');
    });

    it('builds the correct endpoint for different tool names', async () => {
      mockApiService.mockResolvedValue({ text: 'corrected text' });

      await client.executeToolApi('grammar-checker', { text: 'bad grammar' });

      expect(mockApiService).toHaveBeenCalledWith(
        expect.objectContaining({ endpoint: '/api/writing-tools/grammar-checker' }),
      );
    });

    it('returns Result.ok with undefined value when response is empty', async () => {
      mockApiService.mockResolvedValue(undefined);

      const result = await client.executeToolApi('humanize', { text: 'Hello' });

      expect(result.isSuccess).toBe(true);
    });
  });

  // ── writingToolApi (alias) ─────────────────────────────────────────────────

  describe('writingToolApi', () => {
    it('delegates to executeToolApi and returns its result', async () => {
      const responseData = { text: 'Paraphrased output.' };
      mockApiService.mockResolvedValue(responseData);

      const result = await client.writingToolApi('paraphrase', { text: 'Original text', mode: 'standard' });

      expect(result.isSuccess).toBe(true);
      expect(result.getValue()).toEqual(responseData);
      expect(mockApiService).toHaveBeenCalledWith(
        expect.objectContaining({ endpoint: '/api/writing-tools/paraphrase' }),
      );
    });

    it('propagates failures from executeToolApi', async () => {
      mockApiService.mockRejectedValue(new ApiError('Tool not found', 404));

      const result = await client.writingToolApi('nonexistent', {});

      expect(result.isFailure).toBe(true);
      expect(result.error?.statusCode).toBe(404);
    });
  });
});
"}

{"file_path": "src/modules/ai/application/services/__tests__/WritingToolRegistry.test.ts", "initial_content": "/**
 * WritingToolRegistry Unit Tests
 *
 * NOTE: WritingToolRegistry throws if imported in the browser (typeof window !== 'undefined').
 * Jest runs in jsdom, so we must delete `window` before the module is loaded.
 */

// Remove `window` so the registry's browser-guard doesn't throw in jsdom
delete (global as any).window;

import 'reflect-metadata';
import { WritingToolRegistry } from '../WritingToolRegistry';

// ---------------------------------------------------------------------------
// Mock all Genkit flows so no real AI infrastructure is loaded
// ---------------------------------------------------------------------------
jest.mock('@/modules/ai/infrastructure/flows', () => ({
  paraphraseText: jest.fn(),
  summarizeText: jest.fn(),
  humanizeText: jest.fn(),
  grammarCheck: jest.fn(),
  manipulateText: jest.fn(),
  textStyleTune: jest.fn(),
  translateText: jest.fn(),
  writeDocument: jest.fn(),
  rewriteText: jest.fn(),
  summarizeTextWithRatio: jest.fn(),
  readabilityEnhancer: jest.fn(),
  concisenessChecker: jest.fn(),
  clarityAdvisor: jest.fn(),
  aiResearcher: jest.fn(),
  createLectureUnit: jest.fn(),
  generateCitation: jest.fn(),
  generateQuiz: jest.fn(),
  solveAssignments: jest.fn(),
  generateSessionPlan: jest.fn(),
  generateIdeas: jest.fn(),
  detectAiContent: jest.fn(),
  checkBias: jest.fn(),
  checkPlagiarism: jest.fn(),
  checkSentenceStructure: jest.fn(),
  checkFactual: jest.fn(),
  generateProjectBlueprint: jest.fn(),
  topicExplainer: jest.fn(),
  generatePlantUml: jest.fn(),
  generateImage: jest.fn(),
  generateReportSection: jest.fn(),
  generateChapterContent: jest.fn(),
  generateToc: jest.fn(),
  generateUiDescription: jest.fn(),
  generateTheoreticalLecture: jest.fn(),
  literatureReview: jest.fn(),
  academicLiteratureReview: jest.fn(),
  academicPaperQualityChecker: jest.fn(),
  projectDocumentationGenerator: jest.fn(),
  generateReportSectionRag: jest.fn(),
  generateChapterContentRag: jest.fn(),
}));

// Mock Genkit service to prevent server-only module loading
jest.mock('@/modules/ai/infrastructure/services/Genkit', () => ({
  ai: {
    defineFlow: jest.fn(),
    definePrompt: jest.fn(),
  },
  MODEL_BY_TASK: {},
}));

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

describe('WritingToolRegistry', () => {
  let registry: WritingToolRegistry;

  beforeEach(() => {
    registry = new WritingToolRegistry();
  });

  // ── getTool ────────────────────────────────────────────────────────────────

  describe('getTool', () => {
    it('returns a ToolConfig for a known writing tool (summarize)', () => {
      const config = registry.getTool('summarize');

      expect(config).toBeDefined();
      expect(config).toHaveProperty('flow');
      expect(config).toHaveProperty('schema');
      expect(config).toHaveProperty('creditCost');
    });

    it('returns a ToolConfig for the alias "summarizer"', () => {
      const config = registry.getTool('summarizer');
      expect(config).toBeDefined();
    });

    it('returns a ToolConfig for "paraphrase"', () => {
      const config = registry.getTool('paraphrase');
      expect(config).toBeDefined();
      expect(config?.isFreeForGuests).toBe(true);
    });

    it('returns a ToolConfig for "paraphraser" alias', () => {
      const config = registry.getTool('paraphraser');
      expect(config).toBeDefined();
    });

    it('returns a ToolConfig for "humanize"', () => {
      const config = registry.getTool('humanize');
      expect(config).toBeDefined();
      expect(config?.isFreeForGuests).toBe(true);
    });

    it('returns a ToolConfig for "grammar-checker"', () => {
      const config = registry.getTool('grammar-checker');
      expect(config).toBeDefined();
      expect(config?.creditCost).toBe(1);
    });

    it('returns a ToolConfig for "translator"', () => {
      const config = registry.getTool('translator');
      expect(config).toBeDefined();
    });

    it('returns a ToolConfig for "write-document" with higher credit cost', () => {
      const config = registry.getTool('write-document');
      expect(config).toBeDefined();
      expect(config?.creditCost).toBe(2);
    });

    it('returns undefined for an unknown tool name', () => {
      const config = registry.getTool('nonexistent-tool');
      expect(config).toBeUndefined();
    });

    it('returns undefined for an empty string', () => {
      const config = registry.getTool('');
      expect(config).toBeUndefined();
    });

    it('is case-sensitive (uppercase does not match)', () => {
      const config = registry.getTool('SUMMARIZE');
      expect(config).toBeUndefined();
    });
  });

  // ── getAllTools ────────────────────────────────────────────────────────────

  describe('getAllTools', () => {
    it('returns an array of tool name strings', () => {
      const tools = registry.getAllTools();
      expect(Array.isArray(tools)).toBe(true);
      expect(tools.length).toBeGreaterThan(0);
    });

    it('includes core writing tools', () => {
      const tools = registry.getAllTools();
      expect(tools).toContain('summarize');
      expect(tools).toContain('paraphrase');
      expect(tools).toContain('humanize');
      expect(tools).toContain('grammar-checker');
    });

    it('includes academic tools', () => {
      const tools = registry.getAllTools();
      // AcademicToolProvider tools
      expect(tools).toContain('generate-quiz');
      expect(tools).toContain('generate-citation');
    });

    it('includes generation tools', () => {
      const tools = registry.getAllTools();
      // GenerationToolProvider tools
      expect(tools).toContain('generate-ideas');
      expect(tools).toContain('topic-explainer');
    });

    it('returns the same list on multiple calls (no mutation)', () => {
      const first = registry.getAllTools();
      const second = registry.getAllTools();
      expect(first).toEqual(second);
    });
  });

  // ── ToolConfig structure ───────────────────────────────────────────────────

  describe('ToolConfig structure', () => {
    it('every registered tool has a flow function', () => {
      const tools = registry.getAllTools();
      for (const name of tools) {
        const config = registry.getTool(name);
        expect(typeof config?.flow).toBe('function');
      }
    });

    it('every registered tool has a non-negative creditCost', () => {
      const tools = registry.getAllTools();
      for (const name of tools) {
        const config = registry.getTool(name);
        expect(config?.creditCost).toBeGreaterThanOrEqual(0);
      }
    });

    it('every registered tool has a schema with safeParse method', () => {
      const tools = registry.getAllTools();
      for (const name of tools) {
        const config = registry.getTool(name);
        expect(typeof config?.schema?.safeParse).toBe('function');
      }
    });

    it('"write-document" is NOT free for guests', () => {
      const config = registry.getTool('write-document');
      // Either undefined or explicitly false
      expect(config?.isFreeForGuests).toBeFalsy();
    });

    it('free-guest tools have isFreeForGuests set to true', () => {
      const freeTools = ['paraphrase', 'summarize', 'humanize', 'grammar-checker', 'translator'];
      for (const name of freeTools) {
        const config = registry.getTool(name);
        expect(config?.isFreeForGuests).toBe(true);
      }
    });
  });
});
"}

